import { answerQuestion, defaultChatDeps, type ChatDeps } from "./chat";
import { parseChatRequest } from "./chat-request";

// `Env` comes from worker-configuration.d.ts, generated by `pnpm cf-typegen` from wrangler.jsonc.

function jsonResponse(
  data: Record<string, unknown>,
  status = 200,
  extraHeaders: Record<string, string> = {},
): Response {
  return Response.json(data, {
    status,
    headers: {
      "Cache-Control": "no-store",
      ...extraHeaders,
    },
  });
}

// CORS for the web app only. An origin that is not ALLOWED_ORIGIN gets no CORS headers,
// so browsers block the response. This is not authentication; the rate limit (3.8) protects the quota.
function corsHeaders(request: Request, env: Env): Record<string, string> {
  const headers: Record<string, string> = { Vary: "Origin" };
  if (request.headers.get("Origin") === env.ALLOWED_ORIGIN) {
    headers["Access-Control-Allow-Origin"] = env.ALLOWED_ORIGIN;
  }
  return headers;
}

async function handleChat(request: Request, env: Env, deps: ChatDeps): Promise<Response> {
  const cors = corsHeaders(request, env);

  if (request.method === "OPTIONS") {
    // Preflight: no body. Only advertise the allowed method and headers to the allowed origin.
    const allowed = "Access-Control-Allow-Origin" in cors;
    return new Response(null, {
      status: 204,
      headers: {
        "Cache-Control": "no-store",
        ...cors,
        ...(allowed
          ? {
              "Access-Control-Allow-Methods": "POST, OPTIONS",
              "Access-Control-Allow-Headers": "Content-Type",
              "Access-Control-Max-Age": "600",
            }
          : {}),
      },
    });
  }

  if (request.method !== "POST") {
    return jsonResponse(
      { error: "Method not allowed", allowedMethods: ["POST", "OPTIONS"] },
      405,
      { ...cors, Allow: "POST, OPTIONS" },
    );
  }

  const parsed = await parseChatRequest(request);
  if (!parsed.ok) {
    const { status, code, error } = parsed.failure;
    return jsonResponse({ error, code }, status, cors);
  }

  const answered = await answerQuestion(parsed.question, env, deps, cors);
  if ("response" in answered) return answered.response;

  const { status, code, error, retryAfterSeconds } = answered.failure;
  return jsonResponse({ error, code }, status, {
    ...cors,
    ...(retryAfterSeconds !== undefined ? { "Retry-After": String(retryAfterSeconds) } : {}),
  });
}

// `deps` lets tests replace the network and the clock; the deployed Worker uses the defaults.
export function createWorker(deps: ChatDeps = defaultChatDeps) {
  return {
    async fetch(request: Request, env: Env): Promise<Response> {
      const url = new URL(request.url);

      if (url.pathname === "/api/health") {
        if (request.method !== "GET") {
          return jsonResponse(
            {
              error: "Method not allowed",
              allowedMethods: ["GET"],
            },
            405,
          );
        }

        return jsonResponse({
          status: "ok",
          service: "ai-portfolio-assistant-api",
        });
      }

      if (url.pathname === "/api/chat") {
        return handleChat(request, env, deps);
      }

      return jsonResponse(
        {
          error: "Not found",
        },
        404,
      );
    },
  } satisfies ExportedHandler<Env>;
}

export default createWorker();
